(() => {
  const MAX_CARTONS = 48;
  const MAX_KG = 1e3;
  const ALLOWED = ["cartons", "cartonWeightKg"];
  const SPLITTER = 134217729;
  function split(a) {
    const t = SPLITTER * a;
    const hi = t - (t - a);
    return [hi, a - hi];
  }
  function twoProduct(a, b) {
    const p = a * b;
    const [ah, al] = split(a);
    const [bh, bl] = split(b);
    const e = ah * bh - p + ah * bl + al * bh + al * bl;
    return [p, e];
  }
  function fits(c, w) {
    const [p, e] = twoProduct(c, w);
    if (p < MAX_KG) return true;
    if (p > MAX_KG) return false;
    return e <= 0;
  }
  function palletsNeeded(input) {
    const obj = input !== null && typeof input === "object" ? input : {};
    for (const key of Object.keys(obj)) {
      if (!ALLOWED.includes(key)) throw new Error("unknown field: " + key);
    }
    for (const key of ALLOWED) {
      if (!Object.prototype.hasOwnProperty.call(obj, key) || obj[key] === void 0) throw new Error("missing field: " + key);
    }
    const n = obj.cartons;
    const w = obj.cartonWeightKg;
    if (!Number.isSafeInteger(n) || n < 0) throw new Error("invalid cartons");
    if (typeof w !== "number" || Number.isNaN(w) || w <= 0) throw new Error("invalid cartonWeightKg");
    if (w > MAX_KG) throw new Error("carton too heavy for a pallet");
    let c = Math.min(MAX_CARTONS, Math.floor(MAX_KG / w));
    if (c < 0) c = 0;
    while (c > 0 && !fits(c, w)) c--;
    while (c < MAX_CARTONS && fits(c + 1, w)) c++;
    if (c < 1) throw new Error("carton too heavy for a pallet");
    const count = n === 0 ? 0 : n;
    const r = count % c;
    const pallets = (count - r) / c + (r > 0 ? 1 : 0);
    return { pallets: pallets === 0 ? 0 : pallets, cartonsPerPallet: c };
  }
  return { palletsNeeded };
})()

