build.unitScript:
test("100 cartons at 8 kg need 3 pallets, not the 2 from the made-up example", () => {
  assert.deepEqual(code.palletsNeeded({ cartons: 100, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});
test("weight limits a pallet to 40 cartons at 25 kg, so 90 cartons need 3 pallets", () => {
  assert.deepEqual(code.palletsNeeded({ cartons: 90, cartonWeightKg: 25 }), { pallets: 3, cartonsPerPallet: 40 });
});
test("5 cartons at 400 kg fit 2 per pallet and need 3 pallets", () => {
  assert.deepEqual(code.palletsNeeded({ cartons: 5, cartonWeightKg: 400 }), { pallets: 3, cartonsPerPallet: 2 });
});
test("exact fills and one carton over round correctly", () => {
  assert.equal(code.palletsNeeded({ cartons: 96, cartonWeightKg: 8 }).pallets, 2);
  assert.equal(code.palletsNeeded({ cartons: 97, cartonWeightKg: 8 }).pallets, 3);
  assert.deepEqual(code.palletsNeeded({ cartons: 48, cartonWeightKg: 20 }), { pallets: 1, cartonsPerPallet: 48 });
  assert.deepEqual(code.palletsNeeded({ cartons: 3, cartonWeightKg: 1e3 }), { pallets: 3, cartonsPerPallet: 1 });
});
test("zero cartons give 0 pallets and bad weights are rejected", () => {
  assert.equal(code.palletsNeeded({ cartons: 0, cartonWeightKg: 8 }).pallets, 0);
  assert.throws(() => code.palletsNeeded({ cartons: 1, cartonWeightKg: 1001 }), /carton too heavy for a pallet/);
  assert.throws(() => code.palletsNeeded({ cartons: 1, cartonWeightKg: 0 }), /invalid cartonWeightKg/);
  assert.throws(() => code.palletsNeeded({ cartons: 1, cartonWeightKg: -5 }), /invalid cartonWeightKg/);
  assert.throws(() => code.palletsNeeded({ cartons: 1, cartonWeightKg: "8" }), /invalid cartonWeightKg/);
});
test("unknown, missing and invalid carton fields are rejected with the contract messages", () => {
  assert.throws(() => code.palletsNeeded({ cartons: 1, cartonWeightKg: 8, extra: 1 }), /unknown field: extra/);
  assert.throws(() => code.palletsNeeded({ cartonWeightKg: 8 }), /missing field: cartons/);
  assert.throws(() => code.palletsNeeded({ cartons: 1 }), /missing field: cartonWeightKg/);
  assert.throws(() => code.palletsNeeded({ cartons: -1, cartonWeightKg: 8 }), /invalid cartons/);
  assert.throws(() => code.palletsNeeded({ cartons: 1.5, cartonWeightKg: 8 }), /invalid cartons/);
});

build.testScript:
test("carton cap binds and the count rounds up for 100 cartons of 8 kg", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 100, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});
test("weight cap is tighter than 48 for 90 cartons of 25 kg", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 90, cartonWeightKg: 25 }), { pallets: 3, cartonsPerPallet: 40 });
});
test("cartons are not split and total weight alone is not used for 5 cartons of 400 kg", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 5, cartonWeightKg: 400 }), { pallets: 3, cartonsPerPallet: 2 });
});
test("an exact multiple needs no extra pallet for 96 cartons of 8 kg", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 96, cartonWeightKg: 8 }), { pallets: 2, cartonsPerPallet: 48 });
});
test("one carton over an exact multiple rounds up for 97 cartons of 8 kg", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 97, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});
test("48 cartons still under 1000 kg fit on one pallet at 20 kg", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 48, cartonWeightKg: 20 }), { pallets: 1, cartonsPerPallet: 48 });
});
test("a carton over 1000 kg cannot be loaded", function() {
  assert.throws(function() {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: 1001 });
  }, /carton too heavy for a pallet/);
});
test("zero cartons needs zero pallets", function() {
  assert.deepEqual(code.palletsNeeded({ cartons: 0, cartonWeightKg: 8 }), { pallets: 0, cartonsPerPallet: 48 });
});

